MOD = 998244353

def factorial(n):
    if n <= 1:
        return 1
    else:
        return n * factorial(n-1) % MOD

def inv(n):
    if n < 2:
        return n
    else:
        return pow(n, MOD-2, MOD)

def binomial(n, k):
    return factorial(n) * inv(factorial(k)) * inv(factorial(n-k)) % MOD

def is_lucky(ticket):
    half = len(ticket) // 2
    sum1, sum2 = 0, 0
    for i in range(half):
        sum1 += int(ticket[i])
        sum2 += int(ticket[half + i])
    return sum1 == sum2

def count_lucky_tickets(n, k, digits):
    if len(digits) == 1:
        return binomial(2**n, 2**(n//2)) % MOD
    else:
        res = 0
        for d in digits:
            new_digits = digits.copy()
            new_digits.remove(d)
            res += binomial(2**(n-1), 2**(n//2-1)) * count_lucky_tickets(n-1, k, new_digits) % MOD
        return res % MOD

