    for _ in range(m):
        u, v = map(int, input().split())
        if u not in friend_graph:
            friend_graph[u] = []
        if v not in friend_graph:
            friend_graph[v] = []
        friend_graph[u].append(v)
        friend_graph[v].append(u)

    # Determine if any guest has a friend of all others
    all_friends = False
    friends_of_all = set()
    for guest, friends in friend_graph.items():
        if not friends:
            return sys.maxsize
        all_friends = True
        for friend in friends:
            if friend not in friends_of_all:
                friends_of_all.add(friend)
            else:
                all_friends = False
                break

    # If a guest has a friend of all, then the minimum is 1 step
    if friends_of_all:
        return 1

    # Otherwise, find the minimum number of steps required
    steps = 2
    while True:
        step_friends_of_all = 0
        for friend in friend_graph:
            if step_friends_of_all == len(friend_graph[friend]):
                return steps
        for friend in friend_graph:
            for other_friend in friend_graph[friend]:
                if not steps < len(friend_graph[friend]):
                    break
                if steps > len(friend_graph[friend]):
                    steps = len(friend_graph[friend]) - 1
                    break
            else:
                continue
            break
        else:
            break
        steps += 1

