from collections import deque, defaultdict
from math import inf

def build_graph(n, edges):
    graph = defaultdict(dict)
    for u, v, w in edges:
        graph[u][v] = w
        graph[v][u] = w
    return graph

def dijkstra(graph, start, end):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_node = priority_queue.pop(0)
        if current_node == end:
            break
        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                priority_queue.append((distance, neighbor))
    return distances[end]

def calculate_optimal_plan(graph, target_count):
    max_length = 0
    visited = set()
    queue = deque([(0, [0] + list(range(1, target_count + 1)), 0)])
    while queue:
        current_distance, nodes, current_length = queue.popleft()
        if len(nodes) >= len(graph) - 1:
            max_length = max(max_length, current_length)
            break
        for i, node in enumerate(nodes):
            if all(current_length + graph[i][j] for j in nodes):
                new_distance = max_length + current_length + graph[i][next(neighbors for neighbors in graph[i] if node in neighbors)]
                new_nodes = nodes[:]
                new_nodes.remove(node)
                for j, neighbor in enumerate(nodes):
                    if neighbor not in new_nodes:
                        new_length = new_distance - graph[i][j] - node
                        queue.append((new_length, new_nodes, new_length))
    return max_length

