from collections import defaultdict

def calculate_answer(n, m, a, b, *c):
    # Map keys to locks
    key_to_lock = defaultdict(list)
    for i in range(n):
        for j in range(m):
            key_to_lock[b[i]-1].append((i, a[i], c[i][j]-b[i]-1))

    for lock in key_to_lock.values():
        lock.sort(key=lambda x: (x[1] // x[2], -x[1], -x[2]))

    # Determine the answer for every key
    for num_locks in range(n):
        answer = float('inf')
        for locks_used in range(num_locks+1):
            if locks_used > num_locks:
                break
            possible_locks = lock_combinations(key_to_lock, num_locks - locks_used, locks_used)
            answer = min(answer, possible_locks[locks_used] + c_sum(locks_used, key_to_lock))

        if answer < INF:
            return answer

INF = float('inf')
c_sum = lambda *xs: sum(x for xs in xs for x in xs)

def lock_combinations(dicts, used, going_back):
    if used == (1 << len(dicts)) - 1:  # All locks used
        return generate_combinations(dicts)

    if used == (1 << len(dicts)):
        return []

    result = []
    for j in range(len(dicts)):
        result += precalculate(j)

    if not(result):
        return [0] + lock_combinations(dicts, used | (1 << j), going_back+1)  # Generate all combinations with one lock removed
    else:
        return result

def build_combinations(dicts, lock, current, combos):
    if lock == len(dicts):
        combos.append([x[1] for x in current])
        return

    # Set lock has already been used by not set last
    if current[lock+1]:
        build_combinations(dicts, lock+1, current, combos)
        return

    for i in range(dicts[lock][2]):
        if not current[i]:
            current[i] = 1
            build_combinations(dicts, lock+1, current, combos)
            current[i] = 0

def generate_combinations(dicts):
    current = [0] * len(dicts)
    result = []
    build_combinations(dicts, 0, current, result)
    return result

