    def __init__(self, capacity, proportion_of_errors=0.5):
        self.capacity = capacity
        self.proportion_of_errors = proportion_of_errors
        self.hash_functions = []
        for _ in range(capacity // 2):
            hash_function = lambda x: hash(x) % self.capacity
            if len(self.hash_functions) == 0 or not set([hash_function(x) % self.capacity for x in self.hash_functions]) & {hash_function(x) % self.capacity for x in hash_functions}:
