from itertools import product

def calculate_remaining(x, y):
    return sum(xi % p for xi in x) + sum(xj % p for xj in y)

def max_points_available(p, xs, ys):
    available_points = 0
    for rem, triplet in zip([calculate_remaining(x, y) for x, y in zip(xs, ys)], product(range(p), range(p))):
        if rem % p == 0:
            available_points += max((rem // p) - max(triplet // p, 1), 0)
    return available_points

def optimal_strategy(p, xs, ys):
    max_points = 0
    best_strategy = []
    for a, b in product(range(p), range(p)):
        if calculate_remaining(xs, ys)[0] % p >= a and calculate_remaining(xs, ys)[0] % p <= a + max((a//p) - (b // p) - 1, 0) and calculate_remaining(xs, ys)[1] % p >= b and calculate_remaining(xs, ys)[1] % p <= b + max((b//p) - (a // p) - 1, 0):
            points = a % p + b % p
            if points > max_points:
                max_points = points
                best_strategy = ['C' if i < max(a // p, b // p) else 'S' for i in range(len(xs) + len(ys) - 2)]
    return max_points, ''.join(best_strategy)

