def lucky_ticket_count(n, k, digits):
    if n % 2 != 0 or k > 2 or any(i > 3 for i in digits):
        return 0

    dp = [[[0 for _ in range(10)] for _ in range(n+1)] for _ in range(n)]
    for first in digits:
        dp[1][first][0] = 1
    dp[1][0][0] = 1

    for i in range(1, n // 2 + 1):
        for j in digits:
            for a in range(10):
                for mask, count in enumerate(dp[i-1][j]):
                    if mask == 0:
                        dp[i][j][0] = (dp[i][j][0] + count) % MOD
                        dp[i][a][0] = (dp[i][a][0] + count) % MOD
                    else:
                        num = j[:]
                        for l in range(mask):
                            num ^= a
                        dp[i][a][1 + num] = (dp[i][a][1 + num] + count) % MOD

    return (sum(x[y] for x in dp[len(d)/2] for y in range(-1, 1 + len(d)/2)) + 1) % MOD

