    if not matrix == matrix.T:
        return "NOT MAGIC"

    # Iterate through all elements in the matrix
    for i in range(N):
        for j in range(N):
            # Check if the diagonal element equals 0
            if matrix[i][j] != 0:
                return "NOT MAGIC"
            # Check if the adjacent elements are greater than the diagonal element
            for k in range(N):
                if matrix[j][k] >= matrix[i][j]:
                    return "NOT MAGIC"
                if matrix[k][i] >= matrix[i][j]:
                    return "NOT MAGIC"

