# Read input
def read_input():
    n, q = map(int, input().split())
    s = input()
    queries = []
    for _ in range(q):
        l, r = map(int, input().split())
        queries.append((l, r))
    return n, q, s, queries

# Process output
def process_output(res):
    for r in res:
        print(r)

# Print result for each query
def print_result(result):
    for r in result:
        print(r)

def simulate_queries(s, queries):
    # Simulate changes in conveyor symbols based on queries
    for l, r in queries:
        change_symbols(s, r+1, l)

    # Process each query's input and calculate the result
    results = []
    for l, r in queries:
        # Find the number of balls in the last hole
        max_balls_in_hole = 0
        ball_count = 0
        for i in range(l-1, r):
            if s[i] == ' ':
                ball_count = 0
            else:
                ball_count += 1
                max_balls_in_hole = max(max_balls_in_hole, ball_count)

        results.append(max_balls_in_hole)
    return results

def change_symbols(s, left, right):
    modified = False
    for i in range(left-1, right):
        if s[i] == '<':
            s[i] = '>'
            modified = True
        else:
            s[i] = '<'
            modified = True

    if not modified:
        for i in range(left-1, right):
            if s[i] == ' ':
                s[i] = '<'
                modified = True
            else:
                s[i] = ' ' # Mark the hole as capacity 1
                modified = True

    return s

def solve(n, q, s, queries):
    results = simulate_queries(s, queries)
    return results

# Main execution
if __name__ == "__main__":
    n, q, s, queries = read_input()
    results = solve(n, q, s, queries)
    print_result(results)
