def count_balls(query, conveyors):
    q = query.split(' ')
    l, r = int(q[0]) - 1, int(q[1]) - 1
    if q[0] == "1":
        conveyors[l] = ">" if conveyors[l].lower() == "<" else "<"
        conveyors[r] = "<" if conveyors[r].lower() == ">" else ">"
