import sys
from itertools import combinations

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def main():
    N = int(input())
    values = list(map(int, input().split()))

    # Generate all possible edges
    edges = list(combinations(range(1, N+1), 2))

    prime_subsets = set()
    for subset in combinations(range(1, N+1), N-1):
        if sum(values[i-1] for i in subset) in (2*i-1 for i in range(1, N//2+1)):
            prime_subsets.add(subset)

    # Select the maximum number of prime subtrees
    valid_edges = []
    for edge in edges:
        for subset in prime_subsets:
            if sorted(list(subset) + list(edge)) in valid_edges:
                continue
            valid_edges.append(sorted(list(subset) + list(edge)))

    # Output the edges to form the tree
    for edge in valid_edges:
        print(*edge)

if __name__ == "__main__":
    main()
