import sys

def is_magic_matrix(A):
    n = len(A)
    for i in range(n):
        if A[i][i] > 0:
            return False
    for i in range(n):
        for j in range(i, n):
            if A[i][j] > A[i][i] or A[j][i] > A[i][i]:
                return False
    return True

def main():
